{"content": "     1|import { useEffect, useState } from 'react'
     2|import { createParticles } from '../../lib/animations.js'
     3|
     4|export default function VictoryOverlay({
     5|  show, winner, isDraw, lastHash, onNewGame, onReplay, onExport, moveCount,
     6|}) {
     7|  const [particlesCreated, setParticlesCreated] = useState(false)
     8|
     9|  const winnerName = winner === 1 ? '黑方' : winner === 2 ? '白方' : ''
    10|  const displayTitle = isDraw ? '平局' : `${winnerName}胜`
    11|  const shortHash = lastHash ? lastHash.substring(0, 24) + '...' : '—'
    12|
    13|  // 粒子效果
    14|  useEffect(() => {
    15|    if (show && !particlesCreated && !isDraw && winner) {
    16|      // 延迟创建粒子，配合动画时间
    17|      const timer = setTimeout(() => {
    18|        const container = document.querySelector('.victory-particles-container')
    19|        if (container) {
    20|          const cleanup = createParticles(container, {
    21|            count: 30,
    22|            colors: winner === 1 
    23|              ? ['var(--accent-primary)', '#7c3aed', '#00d4ff']
    24|              : ['var(--accent-primary)', '#00ff88', '#00d4ff'],
